import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { ObservabilityEngine } from "../packages/core/src/observability.js";
import {
  type E08ObservabilityFixture,
  e08ObservabilityFixture,
} from "./helpers/e08-observability.js";

describe("E08 independent observer and isolated collection failures", () => {
  let f: E08ObservabilityFixture;
  beforeEach(async () => {
    f = await e08ObservabilityFixture();
  });
  afterEach(async () => {
    await f.store.close();
  });
  it("T-AC-814 reports independent external host loss even while the controller itself is alive", async () => {
    let unavailable = true;
    const engine = new ObservabilityEngine(f.store, {
      now: f.clock.now,
      externalObserver: {
        identity: "independent-fixture",
        async observe() {
          return f.event({
            state: unavailable ? "unavailable" : "healthy",
            code: unavailable ? "REMOTE_HOST_LOST" : "REMOTE_HOST_RECOVERED",
          });
        },
      },
    });
    await engine.collectSystem();
    const first = await engine.health(f.freshOwner());
    expect(first.sources.find((row) => row.source.kind === "external-observer")).toMatchObject({
      freshness: "unavailable",
      observedState: "unavailable",
    });
    expect(first.sources.find((row) => row.source.kind === "controller")).toMatchObject({
      freshness: "fresh",
      observedState: "healthy",
    });
    unavailable = false;
    await engine.collectSystem();
    expect(
      (await engine.health(f.freshOwner())).sources.find(
        (row) => row.source.kind === "external-observer",
      ),
    ).toMatchObject({ freshness: "fresh", observedState: "healthy" });
  });
  it("T-AC-815 isolates an observer outage and retains actual local process measurements", async () => {
    const engine = new ObservabilityEngine(f.store, {
      now: f.clock.now,
      externalObserver: {
        identity: "failed-fixture",
        async observe() {
          throw new Error("Synthetic observer outage");
        },
      },
    });
    await engine.collectSystem();
    const health = await engine.health(f.freshOwner());
    expect(health.sources.find((row) => row.source.kind === "external-observer")).toMatchObject({
      freshness: "unavailable",
    });
    expect(
      (await engine.metrics(f.freshOwner())).records
        .flatMap((row) => row.metrics)
        .some((metric) => metric.name === "process.memory.rss_bytes" && metric.value > 0),
    ).toBe(true);
  });
  it("T-AC-810 reports unavailable filesystem observation as unknown without substituting allocated capacity", async () => {
    const engine = new ObservabilityEngine(f.store, {
      now: f.clock.now,
      localDiskPath: "Z:/synthetic-e08-unavailable-volume",
    });
    await engine.collectSystem();
    expect((await engine.health(f.freshOwner())).sources[0]).toMatchObject({
      freshness: "unknown",
      observedState: "unknown",
    });
    expect(
      (await engine.metrics(f.freshOwner())).records
        .flatMap((row) => row.metrics)
        .map((row) => row.name),
    ).not.toContain("filesystem.total_bytes");
  });
});
